proposal.generator_source:
def make_design(knobs, rng):
    L = int(knobs['L'])
    T = 36
    nw = 3
    nm = 9
    ns = 9
    reps = 6
    B = T // L
    n_events = (reps * nm) // L
    ev_per_word = reps // L
    def build(strict_m, strict_s):
        m_b = np.full(B, n_events // B)
        extra = n_events % B
        if extra > 0:
            idx = rng.choice(B, extra, replace=False)
            m_b[idx] += 1
        slots = [b for b in range(B) for _ in range(int(m_b[b]))]
        evw = [w for w in range(nm) for _ in range(ev_per_word)]
        okm = False
        for _ in range(400):
            rng.shuffle(evw)
            pos = {}
            ok = True
            # assign sorted slots (blocks ascending) to shuffled words
            ss = sorted(slots)
            for b, w in zip(ss, evw):
                for b2 in pos.get(w, []):
                    if b2 == b or (strict_m and abs(b2 - b) < 2):
                        ok = False
                        break
                if not ok:
                    break
                pos.setdefault(w, []).append(b)
            if ok:
                okm = True
                break
        if not okm:
            return None
        massed = [[] for _ in range(T)]
        for w, bl in pos.items():
            for b in bl:
                for t in range(b * L, (b + 1) * L):
                    massed[t].append(w)
        for t in range(T):
            if len(massed[t]) > nw:
                return None
        cap = [nw - len(massed[t]) for t in range(T)]
        for _ in range(300):
            rem = {nm + i: reps for i in range(ns)}
            placed = [[] for _ in range(T)]
            fail = False
            for t in rng.permutation(T):
                for _k in range(cap[t]):
                    cands = []
                    for w, rr in rem.items():
                        if rr <= 0 or w in placed[t]:
                            continue
                        if strict_s:
                            if (t > 0 and w in placed[t - 1]) or (t < T - 1 and w in placed[t + 1]):
                                continue
                        cands.append(w)
                    if not cands:
                        fail = True
                        break
                    mx = max(rem[w] for w in cands)
                    top = [w for w in cands if rem[w] == mx]
                    w = top[int(rng.integers(len(top)))]
                    placed[t].append(w)
                    rem[w] -= 1
                if fail:
                    break
            if not fail and all(v == 0 for v in rem.values()):
                return massed, placed
        return None
    res = None
    for strict_m, strict_s in [(True, True), (False, True), (False, False)]:
        for _ in range(20):
            res = build(strict_m, strict_s)
            if res is not None:
                break
        if res is not None:
            break
    if res is None:
        raise RuntimeError('no design')
    massed, placed = res
    nobj = nm + ns
    omap = rng.permutation(nobj)
    trials = []
    for t in range(T):
        ws = [int(w) for w in massed[t]] + [int(w) for w in placed[t]]
        ws = [ws[i] for i in rng.permutation(len(ws))]
        os_ = [int(omap[w]) for w in ws]
        os_ = [os_[i] for i in rng.permutation(len(os_))]
        trials.append([ws, os_])
    test = []
    for w in rng.permutation(nobj):
        w = int(w)
        test.append({'word': w, 'candidates': [int(o) for o in range(nobj)], 'correct': int(omap[w]), 'group': 'massed' if w < nm else 'spaced'})
    return {'arms': {'a': {'trials': trials, 'test': test}}}

